                       checked="@IsSelected(category)"
                       @onchange="@(e => ToggleCategory(category, (bool)e.Value!))" />
                @category
            </label>
        }
    </div>

    <div class="filter-section">
        <h5>Price Range</h5>
        <div class="price-inputs">
            <input type="number" placeholder="Min" step="0.01"
                   value="@_minPrice"
                   @onchange="@(e => _minPrice = ParseDecimal(e.Value))" />
            <span>–</span>
            <input type="number" placeholder="Max" step="0.01"
                   value="@_maxPrice"
                   @onchange="@(e => _maxPrice = ParseDecimal(e.Value))" />
        </div>
    </div>

    <div class="filter-section">
        <label class="filter-checkbox">
            <input type="checkbox" @bind="_inStockOnly" />
            In Stock Only
        </label>
    </div>

    <div class="filter-actions">
        <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
        <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
    </div>
