{"path": "/tmp/sv-7d14aee876974409a989a36730325ed6/Components/Pages/Catalog/CatalogPagination.razor", "file_text": "@namespace sv_7d14aee876974409a989a36730325ed6.Components.Pages.Catalog

<nav class="catalog-pagination">
    <button class="btn btn-page" disabled="@(CurrentPage <= 1)" @onclick="PreviousPage">
        Previous
    </button>

    @for (int i = 1; i <= TotalPages; i++)
    {
        var pageNum = i;
        <button class="btn btn-page @(pageNum == CurrentPage ? "active" : "")"
                @onclick="@(() => GoToPage(pageNum))">
            @pageNum
        </button>
    }

    <button class="btn btn-page" disabled="@(CurrentPage >= TotalPages)" @onclick="NextPage">
        Next
    </button>
</nav>

@code {
    [Parameter]
    public int CurrentPage { get; set; }

    [Parameter]
    public int TotalPages { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private async Task PreviousPage()
    {
        if (CurrentPage > 1)
            await OnPageChanged.InvokeAsync(CurrentPage - 1);
    }

    private async Task NextPage()
    {
        if (CurrentPage < TotalPages)
            await OnPageChanged.InvokeAsync(CurrentPage + 1);
    }

    private async Task GoToPage(int page)
    {
        await OnPageChanged.InvokeAsync(page);
    }
}
"}

